window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-rastreamento-do-cancer-de-colo-uterino"]={"block":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","label":"Anki · Rastreamento do Câncer de Colo Uterino","count":100,"questions":[{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-8541c9ad520b430d","number":"0201q","sourceNumber":"0201q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 47a, G2P2, retorna à Unidade Básica de Saúde para resultado de colpocitologia oncológica, coletada há um mês. Resultado: atipia de células glandulares sem outras especificações (ACG-SOE). Nega alteração de exame anteriores. A ORIENTAÇÃO É:","options":{"A":"O resultado é anormal; encaminhar para exame de colposcopia e biópsia","B":"O resultado é normal; deverá retornar para coleta de novo exame em três anos","C":"O resultado é anormal e indica infecção por HPV; encaminhar para tratamento com cirurgia de alta frequência","D":"O resultado é anormal, podendo estar associado à infecção por HPV ou processo inflamatório; retornar para coleta de novo exame em 12 meses"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878263","ankiGuid":"*7Vy7<lm+"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-fdb597dc603cace8","number":"0202q","sourceNumber":"0202q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 66a, procura a Unidade Básica de Saúde para rotina de prevenção de câncer de colo uterino. Refere coleta de exames com intervalos trianuais desde os 25 anos, sem alterações. Último exame há um ano, normal. Sem queixas e exame físico normal. ALÉM DE ORIENTAR HÁBITOS DE VIDA SAUDÁVEIS, A CONDUTA É:","options":{"A":"Interromper rastreamento de câncer de colo uterino","B":"Coletar exame de colpocitologia oncológica e retorno para resultado. Se exame normal, interromper o rastreamento","C":"Retornar em dois anos para coleta exame de colpocitologia oncológica. Se exame normal, interromper o rastreamento","D":"Repetir colpocitologia oncótica em dois anos e solicitar ultrassonografia pélvica"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878264","ankiGuid":"Aho,LaPl4t"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-5c46ebf784bc8561","number":"0203q","sourceNumber":"0203q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente, 30 anos, homem transgênero com preservação da vagina. Vida sexual com penetração vaginal, contracepção com DIU de cobre, sem uso de preservativo. Faz uso de terapia hormonal androgênica. Realiza coleta de citologia oncótica. Qual a implicação do ambiente androgênico na avaliação dos achados citológicos?","options":{"A":"diminuição de representação de células superficiais e melhor acurácia diagnóstica","B":"aumento de representação de células superficiais e pior acurácia diagnóstica","C":"diminuição de representação de células basais e melhor acurácia diagnóstica","D":"aumento de representação de células basais e pior acurácia diagnóstica"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878265","ankiGuid":"r4]aXtlxO*"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-2a7aec6a8619b5dc","number":"0204q","sourceNumber":"0204q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 29 anos, tabagista, em relação monogâmica com parceiro fixo, em uso de contraceptivo oral, apresenta resultado positivo para infecção cervical pelo vírus do papiloma humano (HPV). Pode-se afirmar que","options":{"A":"há risco de câncer do colo do útero se infecção persistente pelos subtipos HPV-16 e HPV-18","B":"caso não seja tratada em até 6 meses apresentará alto risco de desenvolvimento de lesões percussoras","C":"a relação monogâmica e uso de contraceptivo são fatores contra o desenvolvimento de câncer de colo uterino","D":"a infecção cervical pelo HPV é permanente e, raramente, regride, espontaneamente","E":"o tabagismo não é um fator de risco para o desenvolvimento de câncer de colo uterino"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878266","ankiGuid":"IEdp/*_JsY"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-3ccdb98ed1b3adf3","number":"0205q","sourceNumber":"0205q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 26 anos, G1P1, assintomática, leva ao ambulatório de ginecologia exame de Papanicolau realizado há 10 dias. O resultado revela cândida sp, lactobacllus e cocos. Diante do achado acima, qual a melhor conduta?","options":{"A":"Independente dos sintomas, os microrganismos possuem importância prognóstica, devendo a paciente ser tratada","B":"O tratamento deve ser estipulado, uma vez que existe associação de bactérias e fungos revelando biota polimicrobiana","C":"Lactobacillus e cocos dispensam tratamento, devendo realizar medicação tópica exclusivamente para a cândida","D":"Deve-se seguir a rotina de rastreamento citológico habitual, estabelecendo tratamento específico nas sintomáticas","E":"Como a paciente é assintomática, a orientação é encaminhar para colposcopia e biópsia se revelar mácula periorificial"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878267","ankiGuid":"sN@n[gd&-*"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-b803acc9e6397637","number":"0206q","sourceNumber":"0206q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 30 anos, G1P1 (cesariana), procurou o serviço de ginecologia com queixa de sangramento genital esporádico há algumas semanas. Traz consigo um exame citológico (Papanicolau) mostrando células glandulares atípicas de significado indeterminado provavelmente não neoplásicas. O exame ginecológico revelou sangramento uterino anormal. De acordo com o cenário acima, qual a melhor conduta?","options":{"A":"Realizar novo exame citológico em três meses","B":"Realizar curetagem do canal endocervical","C":"Realizar colposcopia e avaliação endometrial","D":"Realizar histeroscopia diagnóstica com biópsia","E":"Realizar exérese de zona de transformação tipo 3"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878268","ankiGuid":"C$/9>uP^C("},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-9e0a8c9b0ed9847c","number":"0207q","sourceNumber":"0207q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"São achados colposcópicos que sugerem câncer invasor do colo uterino: I. Vasos sanguíneos no formato de saca-rolhas. II. Contorno irregular da superfície com perda do epitélio superficial. III. Alteração do tom da cor do colo uterino, diferente do rosado. Quais estão corretos?","options":{"A":"Apenas I e II","B":"Apenas I e III","C":"Apenas II e III","D":"I, II e III"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878269","ankiGuid":"cLGX`^mA#}"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-4fbb16ce571e34ae","number":"0208q","sourceNumber":"0208q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Assinale a assertiva correta sobre a vacina contra o papilomavírus humano.","options":{"A":"A vacina protege contra as infecções virais assintomáticas, mas não tem impacto no câncer de colo de útero","B":"A vacina está indicada apenas para quem comprovadamente não teve contato com o vírus","C":"Não é permitido vacinar mulheres com diagnóstico prévio de neoplasia intraepitelial vulvar","D":"A vacina pode ser realizada em outras faixas etárias além daquelas contempladas pelo Programa Nacional de Imunizações, do Ministério da Saúde"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878270","ankiGuid":"gctCB(k2@w"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-5829848353fe36c8","number":"0209q","sourceNumber":"0209q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Conforme as Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero, referentemente ao exame citopatológico (CP) do colo uterino, paciente atendida na UBS deve ser encaminhada para colposcopia se, em","options":{"A":"2 CPs com amostra satisfatória, apresentar células escamosas e metaplásicas imaturas","B":"1 CP com amostra insatisfatória, a leitura for prejudicada pela intensa superposição celular","C":"1 CP com amostra satisfatória, apresentar lesão intraepitelial de baixo grau (LIBG)","D":"1 CP com amostra satisfatória, apresentar células glandulares atípicas (AGC)"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878271","ankiGuid":"Q+NBP34U$Q"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-eb7112c4e475d29a","number":"0210q","sourceNumber":"0210q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"No Brasil, a recomendação do Ministério da Saúde com relação à vacinação contra o Papilomavirus Humano (HPV) para melhor eficácia da vacina é:","options":{"A":"As meninas e meninos devem ser vacinados logo após os 14 anos de idade completos","B":"A vacinação em gestantes deve ser realizada a partir do segundo trimestre","C":"O esquema de vacinação em três doses deve be realizado em mulheres imunossuprimidas","D":"A vacinação deve ser realizada nas meninas após o início da atividade sexual"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878272","ankiGuid":"IH$`1liAKP"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-b208394cfc5b8945","number":"0211q","sourceNumber":"0211q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 40 anos comparece ao ambulatório de patologia cervical com laudo de citologia, indicando células glandulares atípicas, não podendo afastar lesão de alto grau. A colposcopia é satisfatória e normal. Nesse caso, a conduta recomendada é:","options":{"A":"colher nova citologia e realizar ultrassonografia transvaginal","B":"solicitar exames pré-operatórios e indicar conização clássica","C":"prescrever estrogênio tópico e repetir a colposcopia após o uso","D":"curetar o canal cervical e iniciar antibioticoterapia polimicrobiana"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878273","ankiGuid":"bodS%gE}<c"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-95348d5f61f6e32a","number":"0212q","sourceNumber":"0212q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 33 anos, G2PC2, último parto há 3 anos, realizou última coleta de colpocitologia durante o último pré-natal, sem anormalidades citológicas de acordo com a informação da paciente. Refere ciclos menstruais regulares em uso de contraceptivo hormonal injetável mensal. Comparece para checar o resultado da colócitologia que evidencia amostra satisfatória com epitélio metaplásico e cilíndrico e anormalidades em células glandulares sem outras especificações. Qual a conduta mais adequada para esta paciente?","options":{"A":"Realizar cosposcopia","B":"Realizar ultrassom transvaginal","C":"Solicitar biologia molecular","D":"Repetir colpocitologia"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878274","ankiGuid":"F:%5%:}!D"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-75f7d80d04e8a123","number":"0213q","sourceNumber":"0213q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 27 anos apresenta um laudo de colpocitologia oncótica com células escamosas atípicas de significado indeterminado, possivelmente não neoplásicas (ASC-US). Segundo as Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero, a conduta subsequente é:","options":{"A":"Repetir citopatológico em 6 meses","B":"Repetir citopatológico em 12 meses","C":"Realizar colposcopia","D":"Realizar conização","E":"Realizar rastreio citológico trienal"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878275","ankiGuid":"JYDoHs[vwb"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-d11884005b5c0938","number":"0214q","sourceNumber":"0214q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"A fase do ciclo mais adequada para a realização da colposcopia é","options":{"A":"a primeira fase","B":"a segunda fase","C":"o pré-menstrue","D":"a pré-ovulatória"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878276","ankiGuid":"p^du9VAi;;"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-6d26d671d566beee","number":"0215q","sourceNumber":"0215q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"No rastreamento do câncer de colo no Brasil, o Ministério da Saúde tem indicado que","options":{"A":"a citologia seja repetida com intervalo de 6 meses, em mulheres com idade superior a 30 anos, com resultado mostrando ASC-US","B":"a citologia pode ser realizada a cada cinco anos, entre a idade de 30 a 64 anos, desde que dois exames, com intervalos anuais, sejam negativos","C":"o início do rastreamento seja realizado a partir de 25 anos de idade, em todas as mulheres que iniciaram atividade sexual","D":"o rastreamento com citologia em todas as mulheres com idade entre 25 a 64 anos, com atividade sexual, em intervalos trienais"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878277","ankiGuid":"r>MNANXq1#"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-08009aecefdc8875","number":"0216q","sourceNumber":"0216q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 43 anos de idade, com abstinência sexual há 15 anos e papanicolau sem alterações significativas há 2 anos, vai à consulta na UBS muito preocupada com risco de câncer de colo uterino pois sua vizinha foi diagnosticada recentemente com essa afecção. A orientação mais adequada é:","options":{"A":"Realizar colposcopia e vulvoscopia","B":"Discutir a histerectomia profilática","C":"Não há indicação de coleta cérvico-vaginal","D":"Indicar a realização de teste DNA-HPV"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878278","ankiGuid":"ycFS4eS~o+"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-9642f071651818b7","number":"0217q","sourceNumber":"0217q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Após 6 meses de um resultado de citologia oncótica de colo uterino com resultado de atipia de células escamosas, provavelmente não neoplásicas (ASC-US), uma paciente de 34 anos repete o exame e apresenta o resultado: lesão intraepitelial de baixo grau (LIEBG). De acordo com as Diretrizes para o Rastreamento do Câncer do Colo do Útero, o próximo passo para o tratamento adequado é:","options":{"A":"Nova coleta de citologia oncótica em 12 meses","B":"Realizar teste de DNA-HPV","C":"Nova coleta de citologia oncótica em 6 meses","D":"Encaminhar paciente à colposcopia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878279","ankiGuid":"f}p$![L#0k"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-1e3904930b9b9e0e","number":"0218q","sourceNumber":"0218q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"VSS, 36 anos, G4P4A0, comparece a UBS para receber resultado de citologia cérvico-vaginal colhida há 1 mês, que revelou ASC-US (Células escamosas atípicas de significado indeterminado). Qual a melhor conduta?","options":{"A":"Colposcopia e avaliação endometrial","B":"Manter periodicidade normal das suas citologias pois este achado não representa nenhum risco","C":"Manter vigilância com citologia e encaminhar para colposcopia apenas se novos exames alterados","D":"Colposcopia imediata, pela grande probabilidade de este achado citológico indicar a presença de lesão pré-neoplásica do colo uterino"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878280","ankiGuid":"fLPYJ$^E#E"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-a0b9ac653cbecad2","number":"0219q","sourceNumber":"0219q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"A prevenção do câncer de colo uterino, em seus cinco níveis, requer o conhecimento sobre os fatores de risco, rastreamento, diagnóstico e tratamento das lesões precursoras e das lesões invasoras. Assim, sobre as estratégias de prevenção do câncer de colo uterino no Brasil, assinale a alternativa correta.","options":{"A":"O exame de Papanicolaou do colo uterino deve ser realizado em mulheres de 25 a 64 anos de idade completos","B":"A realização do exame de Papanicolaou do colo de útero deve ser realizado de forma anual, independentemente de resultados anteriores","C":"Não se deve colher exame de Papanicolaou do colo uterino de gestantes","D":"As mulheres devem ser submetidas à coleta de Papanicolaou do colo uterino assim que iniciarem a atividade sexual","E":"A idade para a vacinação contra HPV em meninas, preconizada pelo Programa Nacional de Imunizações no Brasil, é de 9 – 16 anos"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878281","ankiGuid":";vOSp?2so"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-1612ddb9feb18045","number":"0220q","sourceNumber":"0220q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 26 anos nunca realizou citologia oncológica (CO) e vem para sua primeira consulta com ginecologista. Paciente sem queixas. Nega comorbidades. Foi realizado exame físico completo e coleta de CO. No retorno, traz resultado que mostra células escamosas atípicas de significado indeterminado, não se podendo afastar lesões neoplásicas (ASC-H) de alto grau. De acordo com as Diretrizes Brasileiras para o rastreamento do câncer do colo uterino e o INCA/Ministério da Saúde, a paciente deverá","options":{"A":"ser tranquilizada e repetir CO com 6 meses","B":"realizar conização de imediato","C":"ser tranquilizada e repetir CO com 12 meses","D":"realizar colposcopia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878282","ankiGuid":"(<4gHyipQ"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-f86ff4f0f6989c5c","number":"0221q","sourceNumber":"0221q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 32 anos comparece à consulta para mostrar resultado de colpocitologia cujo laudo indica lesão de alto grau, não podendo excluir carcinoma epidermoide invasor. Diante desse resultado, a conduta adequada é indicar:","options":{"A":"conização","B":"colposcopia","C":"histerectomia total","D":"cirurgia de Piver 3"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878283","ankiGuid":"wN%{!~wkl3"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-401dc333ef96678a","number":"0222q","sourceNumber":"0222q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"João, homem trans de quarenta anos de idade, foi à consulta de acompanhamento de hormonização, na UBS, com seu médico de família. Entre os temas tratados na consulta, o médico abordou os rastreamentos populacionais para ele. Com base nesse caso hipotético e no que determina o Ministério da Saúde, o rastreamento mais apropriado, considerando-se que João esteja sem sintomas na consulta e não possua antecedentes familiares de neoplasias, seria","options":{"A":"PSA total e livre e toque retal","B":"PSA total e livre","C":"colpocitologia oncótica e ultrassonografia das mamas","D":"somente colpocitologia oncótica","E":"colpocitologia oncótica e mamografia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878284","ankiGuid":"d%JCPVcN6]"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-90089ef805a729f9","number":"0223q","sourceNumber":"0223q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma mulher de 33 anos de idade, em atividade sexual desde os vinte anos de idade, iniciou coleta de citologia oncológica (Papanicolau) aos 25 anos, tendo feito o exame aos 26 anos, aos 29 anos e há cerca de um ano, aos seus 32 anos, todos com resultado negativo para neoplasia ou lesão precursora de câncer. Como faz anualmente, foi ao ginecologista para consulta de rotina, sendo que teve de trocar de médico por causa do plano de saúde. Não apresenta queixas ou antecedentes mórbidos e possui parceiro único. O profissional que a atendeu solicitou uma bateria de exames e realizou a coleta de material para a citologia oncológica (Papanicolau). Com base nesse caso hipotético, é correto afirmar que o profissional","options":{"A":"agiu corretamente ao coletar o material para a citologia oncológica (Papanicolau), pois esse exame deve ser realizado anualmente","B":"deveria ter solicitado uma colposcopia, pois não é possível afirmar sobre a promiscuidade do parceiro","C":"se precipitou ao coletar o material para a citologia oncológica (Papanicolau), pois, no caso da paciente, esse exame pode ser feito a cada três anos","D":"agiu corretamente ao coletar o material para a citologia oncológica (Papanicolau), pois a paciente não apresentava três exames consecutivos negativos","E":"agiu corretamente ao coletar o material para a citologia oncológica (Papanicolau), uma vez que a paciente não possui resultado negativo de captura híbrida para HPV"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878285","ankiGuid":"D=@/o/SSi?"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-efe75227af8e5bc1","number":"0224q","sourceNumber":"0224q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 58 anos apresenta lesões assintomáticas na vulva há seis meses, conforme a imagem. Antecedente pessoal: HAS e portadora do HIV, com carga viral indetectável e CD4+ 300 células/mm³, em uso regular de TARV e captopril. Refere prática sexual sem preservativo no último ano, porém, sem parceiro fixo.\n\nDe acordo com seu diagnóstico, pode-se afirmar que as lesões vulvares","options":{"A":"podem ser tratadas ambulatorialmente com ácido tricloroacético 90%","B":"são causadas por HPV de alto risco oncogênico","C":"são devido à sífilis maligna precoce no HIV, devendo ser tratadas com penicilina benzatina, 2400000 UI, intramuscular, dose única","D":"são de molusco contagioso em paciente imunossuprimido e devem ser tratadas com curetagem"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":["question_bank/media/ginecologia-rastreamento-do-cancer-de-colo-uterino/paste-947c0cd24494ca0b12cf4265f09e96069ba90823.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878286","ankiGuid":"znw#=)zPNK"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-2364f628aca4edac","number":"0225q","sourceNumber":"0225q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 35 anos apresenta lesão intraepitelial de alto grau em citologia oncótica de colo uterino (HSIL). Colposcopia: zona de transformação tipo 1 com áreas de epitélio branco espesso e mosaico grosseiro, restritas ao colo, sem sinais de invasão ou doença glandular. A conduta correta é:","options":{"A":"repetir a citologia oncótica, direcionando a coleta de amostras das áreas alteradas, sob colposcopia","B":"propor o “ver e tratar” e realizar exérese da zona de transformação do tipo 1","C":"solicitar a genotipagem de HPV e agendar retorno breve","D":"solicitar a revisão da lâmina e propor rastreamento para cervicites"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878287","ankiGuid":"d]H<S9{?*5"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-5b0037cf6df5cd07","number":"0226q","sourceNumber":"0226q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher com 35 anos, III gesta III para, portadora de metrorragia por miomatose, sempre apresentou colpocitologia oncologia negativa e teve indicada histerectomia total, e a peça cirúrgica confirmou esse diagnóstico. Quanto aos exames preventivos a serem realizados a partir da cirurgia,","options":{"A":"devem continuar a ser anuais","B":"devem ser realizados a cada 5 anos","C":"devem ser a cada 3 anos","D":"podem ser dispensados","E":"devem ser complementados com colposcopia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878288","ankiGuid":"uG(O@sX#L?"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-9c4aa29b33805f41","number":"0227q","sourceNumber":"0227q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Em mulheres assintomáticas que, ao exame ginecológico, foram diagnosticadas com ectopia ou distopia, o que faz com que o epitélio da endocérvice fique para fora do orifício externo anatômico do colo uterino, a melhor conduta será a","options":{"A":"eletrocauterização do colo uterino, pela possibilidade aumentada de contrair infecção por HPV","B":"conduta expectante","C":"aplicação de ácido tricloroacético","D":"vaporização com laser","E":"cauterização e o tratamento para Chlamydia, cuja infecção é geralmente assintomática"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878289","ankiGuid":"ro1TdVHx|n"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-c4382e14e5226cd5","number":"0228q","sourceNumber":"0228q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 19 anos, G=1, P=0, A=1, coitarca aos 14 anos, usuária de contraceptivo hormonal oral, procurou serviço médico em UBS por conta de corrimento vaginal mucoso de longa data. Realizada a coleta de colpocitologia oncótica, que mostrou suspeita de lesão intra-epitelial cervical de alto grau - (NIC=II/III). Submetida à colposcopia e biópsia de lesão, em área de pontilhado fino, foi diagnosticada como NIC=II. A conduta ideal para esta paciente é:","options":{"A":"Histerectomia simples abdominal ou vaginal","B":"Conização de colo de útero com bisturi a frio","C":"Seguimento com colpocitologia e colposcopia semestrais por 2 anos","D":"Conização de colo de útero com alça (cirurgia de alta frequência - CAF)"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878290","ankiGuid":"JYIVft`x9)"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-e35e0b321154aaa1","number":"0229q","sourceNumber":"0229q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"A recomendação correta frente a um resultado alterado na citologia cervicovaginal com","options":{"A":"lesão de alto grau (HSIL) é colher DNA-HPV em 12 meses","B":"AGC (células glandulares atípicas de significado indeterminado) é repetir citologia em 6 meses","C":"AOI (células atípicas de origem indefinida) é repetir citologia em 6 meses","D":"lesão de baixo grau (LSIL) é repetir citologia em 6 meses","E":"ASCUS entre 25 a 29 anos de idade é repetir citologia em 12 meses"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878291","ankiGuid":"rW,vH)@FsJ"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-b1ed814ac79bea4a","number":"0230q","sourceNumber":"0230q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Acerca da vacina contra o papiloma vírus humano (HPV) é correto afirmar que","options":{"A":"apenas pacientes virgens devem ser vacinadas","B":"para homens pode ser feita, segundo a bula, até os 42 anos de idade","C":"recentemente foi liberada pelo Sistema Único de Saúde (SUS) para imunocomprometidas até os 45 anos de idade","D":"para mulheres, segundo a bula, pode ser feita até os 52 anos de idade","E":"a idade de início para meninas no SUS é de 7 anos de idade"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878292","ankiGuid":"yK-[_l,uI2"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-6e0344be9a400a41","number":"0231q","sourceNumber":"0231q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 32 anos de idade, com diagnóstico anatomopatológico de lesão intraepitelial de alto grau. Nesse caso, qual a melhor conduta terapêutica?","options":{"A":"As lesões de alto grau de colo uterino são sempre tratadas com conização e lâmina fria","B":"A conduta deve ser expectante pela idade da paciente","C":"Indicar histerectomia","D":"A cauterização química com ácido tricloroacético","E":"A conização que pode ser a frio ou com alça de alta frequência"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878293","ankiGuid":"xdBB(4aK5T"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-80efcd5737026edd","number":"0232q","sourceNumber":"0232q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"O achado visto ao exame citopatológico de colo uterino (imagem abaixo) sugere a possibilidade de contaminação por:","options":{"A":"Clamídia trachomatis","B":"Trichomonas vaginalis","C":"Herpes simplex tipo 2","D":"papilomavírus humano"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":["question_bank/media/ginecologia-rastreamento-do-cancer-de-colo-uterino/paste-6698e9ee25957921ad9161bd07bdb0e803984590.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878294","ankiGuid":"L>_:^z1[Q1"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-7463123ed0d02aaf","number":"0233q","sourceNumber":"0233q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 23a, procura o Unidade Básica de Saúde para consulta ginecológica de rotina, refere vida sexual ativa há 10 meses. Antecedente pessoal: transplante renal, em terapia imunossupressora. A ORIENTAÇÃO EM RELAÇÃO À PREVENÇÃO DE CÂNCER DE COLO UTERINO É:","options":{"A":"Coleta de colpocitologia oncológica aos 25 anos, com intervalo anual nos dois primeiros exames. Não há indicação de vacinação pela faixa etária","B":"Coleta de colpocitologia oncológica agora, com intervalo anual. Indicada vacinação para HPV com duas doses tempo 0-6 meses","C":"Coleta de colpocitologia oncológica aos 25 anos, com intervalo anual nos dois primeiros exames. A vacina é contraindicada para população transplantada","D":"Coleta de colpocitologia oncológica agora com intervalo semestral no primeiro ano. Vacinação para HPV com três doses tempo 0-3-12 meses"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878295","ankiGuid":"m!?Bv4r%l:"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-502f77e04b9062bf","number":"0234q","sourceNumber":"0234q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 32a, G3P2A0, comparece para primeira consulta de pré-natal com 15 semanas de amenorreia. Última citologia oncótica de colo uterino com resultado de lesão intra-epitelial de baixo grau, realizada há dois anos. A CONDUTA É:","options":{"A":"Realizar colposcopia após 20 semanas de gestação","B":"Realizar colposcopia após o parto","C":"Coletar citologia oncótica de colo uterino em 1 ano","D":"Coletar citologia oncótica de colo uterino nesta consulta"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878296","ankiGuid":"q7A-+dP7Ze"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-90f3384fdca463f5","number":"0235q","sourceNumber":"0235q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Segundo a Organização Mundial da Saúde, o climatério compreende o período de vida da mulher entre o final da fase reprodutiva e a senilidade. Em geral, varia dos 40 aos 65 anos. Nesse período, ocorre a menopausa, definida como a interrupção permanente da menstruação após 12 meses de amenorreia. Sobre o climatério, sabe-se que:","options":{"A":"o diagnóstico deve ser confirmado com as dosagens de prolactina e LH","B":"os fogachos são sensações transitórias súbitas de calor que se iniciam nos pés e sobem em direção às pernas e joelhos","C":"dentre os exames complementares para sua propedêutica, a RNM de tórax e cintilografia óssea são mandatórias","D":"a mamografia e a colpocitologia oncoparasitária são fundamentais na propedêutica básica do climatério"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878297","ankiGuid":"xyjN^[i4=@"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-9ac7a553c2135754","number":"0236q","sourceNumber":"0236q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 55 anos de idade foi submetida à colposcopia, por apresentar ASCH no exame de Papanicolau. Na colposcopia, foi evidenciada JEC justa orificial e presença de pontilhado grosseiro adentrando o canal endocervical, com visualização completa da lesão. Com base nesse caso hipotético, assinale a alternativa que apresenta, correta e respectivamente, o provável diagnóstico anatomopatológico e conduta a ser adotada.","options":{"A":"NIC 1 e seguimento em seis meses","B":"NIC 1 e seguimento em um ano","C":"NIC 2 e CAF com excisão do tipo 1","D":"NIC 2 e CAF com excisão do tipo 2","E":"NIC 2 e CAF com excisão do tipo 3"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878298","ankiGuid":"h})mA;Vp<)"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-fd11e2ad90958e78","number":"0237q","sourceNumber":"0237q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 20 anos, comparece à consulta, pois realizou um exame colpocitológico para rastreio de câncer de colo, há 1 mês, e o resultado foi de lesão intraepitelial de baixo grau (LSIL). Assustada, buscou uma segunda opinião médica. Considerando-se as Diretrizes Brasileiras para o rastreamento do câncer do colo uterino do Ministério da Saúde de 2016, a conduta mais apropriada é recomendar a essa paciente que:","options":{"A":"realize colposcopia imediatamente","B":"repita nova citologia em 1 ano","C":"repita nova citologia em 3 anos","D":"realize a captura híbrida para vírus do papiloma humano"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878299","ankiGuid":"zxNgb7S6lE"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-139bb0953a51f9e0","number":"0238q","sourceNumber":"0238q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"A coleta dupla é preconizada no sistema público de saúde do Brasil como forma de rastreamento do câncer de colo uterino. Correlacione os números da figura abaixo com a sequência correta da coleta dupla, a qual inicia com a colocação do espéculo de:","options":{"A":"Cusco (2), seguida do raspado da ectocérvice em 360º com a espátula (7) com a parte redonda, dilatação do colo com (5), raspado do canal cervical, em movimentos de vai e vem e rotação com (8), pôr o material colhido em camada espessa em (1) e fixação com (3), limpeza da vagina com gaze montada em Cheron (4)","B":"Collins (2), seguida da remoção do excesso de secreção com algodão montado em pinça (4), raspado em 360º da ectocérvice com espátula (7), introdução da escova (8) a 1,5 cm do colo, em movimentos de vai e vem e rotação e colocação do material colhido em camada fina em (1) e fixação imediata com (3)","C":"Graeve (2), seguida da remoção do excesso de secreção com algodão com pinça (4), introdução da escova (8) a 1,5 cm do colo, em movimentos de vai e vem e rotação, raspado da ectocérvice em 360º com espátula (7), colocação do material colhido em duas camadas separadas em (1) e fixação imediata com éter (3)","D":"Pederson (2), seguida da coleta de material do fundo de saco vaginal com a parte redonda da espátula de Ayre (7), raspado da ectocérvice em 360º com a borda em rabo-de-peixe de (7), colocação do material colhido com a espátula de Ayre em camadas finas em lâminas separadas (1) e fixação imediata com álcool a 70% (3)"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":["question_bank/media/ginecologia-rastreamento-do-cancer-de-colo-uterino/paste-3022526cd8413c5ff850fb8fd538ae5331b83ee9.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878300","ankiGuid":"pF6RbOL^Qp"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-840b4cbdb1456faa","number":"0239q","sourceNumber":"0239q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 28 anos, sexualmente ativa, apresenta colo uterino com área acetobranca com pontilhado fino. A citologia do raspado cervical (em meio líquido) está representada abaixo.\n\nO diagnóstico mais provável é:","options":{"A":"Tricomoníase","B":"Gardnerella vaginalis","C":"Papilomavírus humano","D":"Candidíase"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":["question_bank/media/ginecologia-rastreamento-do-cancer-de-colo-uterino/paste-22a4c8d836044fd72574bdc29294aacf0b0f581d.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878301","ankiGuid":"rX{vg%`3q8"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-55dfbb5c68a2a069","number":"0240q","sourceNumber":"0240q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 32 anos, G1P1, usuária de implante de etonogestrel, vivendo com HIV há 5 anos em uso de terapia antirretroviral com carga viral abaixo do limite de detecção e contagem de linfócitos TCD4 de 350 células/mm³. Resultado da colpocitologia coletada há 1 mês: amostra satisfatória, epitélio escamoso glandular e células compatíveis com lesão intraepitelial de baixo grau. De acordo com as Diretrizes Brasileiras do Instituto Nacional do Câncer (2016), qual melhor conduta?","options":{"A":"Realizar colposcopia imediatamente","B":"Coletar biologia molecular","C":"Repetir a citologia em seis meses","D":"Realizar tratamento excisional"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878302","ankiGuid":"p+sv*$Gf-W"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-34d5a0914766c37f","number":"0241q","sourceNumber":"0241q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Primigesta, 16 anos, 21 semanas, refere lesões na vulva há 30 dias. Na consulta Unidade Básica de Saúde, a avaliação da genitália evidencia as lesões mostradas na figura 1.\n\nQual a melhor conduta para esse caso?","options":{"A":"Ácido tricloacético 80%","B":"Podofilotoxina","C":"Expectante","D":"Imiquimode"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":["question_bank/media/ginecologia-rastreamento-do-cancer-de-colo-uterino/paste-6eacf219f651b6cc223bc843b86a1ac3bb38fbc5.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878303","ankiGuid":"EtG!-~~8O`"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-2904b6bfaefd5c05","number":"0242q","sourceNumber":"0242q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 23 anos procura a UBS para coleta de exame preventivo do câncer de colo uterino. Refere menarca aos 13 anos e sexarca aos 17. Informa que já teve relações sexuais com homens, mas atualmente mantém relações apenas com mulheres. Nesse caso, segundo as diretrizes do Ministério da Saúde, o profissional de saúde deve orientar à paciente que no momento:","options":{"A":"será colhido o exame e que ela deverá manter o rastreamento anual até os 64 anos de idade","B":"será colhido o exame e que ela deverá manter o rastreamento trienal até os 64 anos de idade","C":"não será colhido o exame e que ela deverá retornar apenas caso volte a ter relações sexuais com homens","D":"não será colhido o exame e que ela deve retornar aos 25 anos, idade em que é iniciado o rastreamento desse tipo de câncer"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878304","ankiGuid":"M{|+u[X,QM"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-56d09fcbc12b3d60","number":"0243q","sourceNumber":"0243q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 38 anos comparece à consulta de ginecologia para mostrar resultado de exame preventivo com seguinte laudo: “Amostra satisfatória. Microbiologia: Candida albicans. Células glandulares atípicas de significado indeterminado”. Nega sintomas de odor, prurido ou secreção vaginal. A conduta recomendada pelo Ministério da Saúde é:","options":{"A":"solicitar exame de imagem e encaminhar para colposcopia","B":"solicitar exame de imagem e repetir o exame em 6 meses","C":"tratar candidíase e encaminhar para colposcopia","D":"tratar candidíase e repetir o exame em 6 meses"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878305","ankiGuid":"GN>GON.T5Z"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-578381e18224e224","number":"0244q","sourceNumber":"0244q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Adolescente de 15 anos queixa-se de nódulos vulvares. Relata vida sexual com parceiro fixo há 1 ano e utilização de contraceptivo oral, sem uso de preservativo. Exame físico: pequenas verrugas pedunculadas no introito vaginal e na região perianal. O agente etiológico é:","options":{"A":"Herpes vírus","B":"Haemophylus ducreyi","C":"Chlamydia trachomatis","D":"Papilomavírus humano"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878306","ankiGuid":"Bu^Y,ASs#g"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-cfa8c6c910dc0969","number":"0245q","sourceNumber":"0245q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente com 35 anos de idade, G=3 P=3 A=0, encaminhada da Unidade Básica de Saúde (UBS) com resultado de Colpocitologia Oncótica (CO) de Lesão intra-epitelial de alto grau (LIE-AG). Qual das alternativas abaixo é o próximo passo para esta paciente?","options":{"A":"Realizar Colposcopia","B":"Realizar Histerectomia Total","C":"Fazer acompanhamento da lesão com CO de 6/6 meses","D":"Repetição da CO em 6 meses, se persistir, fazer Colposcopia"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878307","ankiGuid":"O0J4=MWAzc"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-a60020360380dda3","number":"0246q","sourceNumber":"0246q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 19 anos idade, em consulta de rotina na Unidade Básica de Saúde. Vida sexual ativa, com parceiro único há 2 anos. Em uso de DIU de cobre. Na consulta, a paciente questiona quanto à necessidade de realização de citologia oncótica de colo uterino. Na orientação, o profissional de saúde dirá que esta paciente deverá:","options":{"A":"Iniciar a realização do procedimento na presente consulta, repetindo-o anualmente até os 30 anos de idade","B":"Iniciar a realização do procedimento aos 25 anos de idade","C":"Iniciar a realização do procedimento na presente consulta repetindo-o a cada 3 anos, após dois exames anuais normais","D":"Realizar o procedimento uma vez ao ano até os 25 anos de idade, com colposcopia com biópsia a cada 5 anos"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878308","ankiGuid":"m.[0]`rT$i"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-ec73224223f36571","number":"0247q","sourceNumber":"0247q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 19 anos de idade, retorna em consulta com resultado de Papanicolau de 12 meses atrás: Células Escamosas Atípicas de Significado Indeterminado - ASC-US. Considerando os protocolos atuais, qual é a conduta indicada?","options":{"A":"Indicar conização","B":"Coletar novo Papanicolau","C":"Encaminhar à colposcopia","D":"Realizar nova coleta após os 25 anos de idade"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878309","ankiGuid":"w|eFKPSk]3"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-3f2003b435f6f507","number":"0248q","sourceNumber":"0248q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 23 anos de idade, com vida sexual ativa e assintomática, realizou colpocitologia cujo resultado foi lesão intraepitelial escamosa de baixo grau. Teste de HPV-DNA foi negativo. Com base nesse caso hipotético, assinale a alternativa que apresenta a conduta mais adequada segundo o Ministério de Saúde.","options":{"A":"repetir colpocitologia em três anos","B":"repetir exames imediatamente","C":"colposcopia","D":"cauterização da zona de transformação","E":"excisão da zona de transformação"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878310","ankiGuid":"lTJ`Mi/kqe"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-cde435b69c63a4da","number":"0249q","sourceNumber":"0249q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"No que se refere às doenças causadas pelo papilomavírus humano (HPV), assinale a alternativa correta.","options":{"A":"As mulheres com verrugas anogenitais requerem um exame ginecológico completo, incluindo o exame preventivo de câncer de colo do útero, uma vez que a maioria das verrugas são provocadas por tipos de alto risco oncogênico","B":"Não há indicação de parto cesáreo devido à presença de lesões de verrugas genitais, ainda que haja a possibilidade de transmissão destas ao recém-nascido. A indicação excepcional seria a obstrução do canal de parto ou sangramento","C":"O HPV pode ser classificado em tipos de baixo risco oncogênico e em tipos de alto risco oncogênico. Sendo assim, como método de prevenção primária, são recomendados testes que identifiquem os diferentes tipos de HPV na rotina clínica e no rastreamento de pessoas assintomáticas","D":"A vacinação das pessoas que vivem com HIV é contraindicada, devido ao potencial risco de contaminação desses pacientes pela vacina","E":"Apenas pacientes do sexo feminino com lesões anais devem ter um exame proctológico com anuscopia e toque retal"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878311","ankiGuid":"wd=b}8h=f]"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-e7b854259b0aea76","number":"0250q","sourceNumber":"0250q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 65 anos, vem à consulta na Unidade Básica de Saúde para avaliação de abaulamento genital. Nunca havia consultado com ginecologista anteriormente. Gesta IV. para IV, quatro partos normais. Dois parceiros. Menopausa aos 51 anos. De acordo com o Ministério da Saúde, a conduta visando à prevenção do câncer de colo uterino dessa paciente deve ser","options":{"A":"dispensar o rastreio, uma vez que a paciente já passou da faixa etária preconizada, que vai até 64 anos","B":"colher duas citologias com intervalo de um a três anos e, se ambas estiverem negativas, dispensar do rastreio","C":"colher duas citologias com intervalo de um a três anos e, se ambas estiverem negativas, manter rastreio trienal","D":"colher duas citologias com intervalo de um ano e, se ambas estiverem negativas, manter rastreio trienal por mais 10 anos","E":"colher uma citologia e, se estiver negativa, dispensar do rastreio, porque a paciente tem mais de 64 anos"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878312","ankiGuid":"s?h`0wy4bo"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-8c445f7efffc50cb","number":"0251q","sourceNumber":"0251q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"O câncer invasor do colo do útero é considerado um câncer evitável porque o estágio pré-invasor é longo e os programas de rastreamento por exame colpocitológico possibilitam tratamento das lesões pré-invasoras de modo eficaz. A respeito da prevenção e rastreamento do câncer de colo uterino, assinale a alternativa CORRETA:","options":{"A":"A duração da imunidade conferida pela vacina quadrivalente para o HPV está bem estabelecida, mesmo quando administrada após os 25 anos de idade","B":"A vacina contra o HPV é uma ferramenta bem estabelecida de prevenção secundária das lesões precursoras do câncer do colo uterino","C":"As mulheres que receberam a vacina contra o HPV antes de iniciarem a atividade sexual, não precisam fazer a colpocitologia oncótica como método de rastreamento para o câncer do colo uterino, mesmo após iniciarem vida sexual","D":"Meninas de 9 a 14 anos e meninos de 11 a 14 anos podem tomar a vacina contra o HPV gratuitamente no Sistema Único de Saúde. Para os portadores do HIV, a faixa etária é mais ampla (9 a 26 anos) e o esquema vacinai é de três doses (intervalo de 0, 2 e 6 meses)"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878313","ankiGuid":"k?am7O?@3m"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-c7f3278a55cec3cd","number":"0252q","sourceNumber":"0252q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 35 anos de idade, trouxe exame citológico cérvico-vaginal com lesão de alto grau. Realiza colposcopia com a junção escamo-colunar (JEC) completamente visível e área de epitélio acetobranco denso margeando a JEC de 11 a 1 hora ectocervical (zona de transformação tipo 1). De acordo com as diretrizes de rastreamento do câncer de colo uterino (2016) do Ministério da Saúde, a conduta é:","options":{"A":"biópsia da atipia colposcópica","B":"cauterização da lesão","C":"excisão da zona de transformação","D":"curetagem de canal endocervical"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878314","ankiGuid":"h1RN.`l=2I"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-38a14aa6d27a974e","number":"0253q","sourceNumber":"0253q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Há muito se investiga a correlação entre o HPV (Vírus do Papiloma Humano) e a neoplasia cervical e até o momento foram descobertos mais de 120 tipos de HPV no trato genital. Dentre eles, a maior correlação com a neoplasia de colo uterino ou de maior potencial oncogênico inclui os tipos:","options":{"A":"6 e 11","B":"16 e 18","C":"31 e 33","D":"43 e 44"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878315","ankiGuid":"jP<kzQCIU,"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-8a87e621f8ff7670","number":"0254q","sourceNumber":"0254q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"No rastreamento do câncer genital feminino através da citologia oncótica, é correto afirmar que:","options":{"A":"Não deve ser realizado em gestante pelo baixo risco do câncer do colo uterino nesta condição","B":"Deve ser realizado com maior frequência nas mulheres na pós-menopausa pelo risco provocado pelo desequilíbrio hormonal","C":"Deve ser realizado em mulheres submetidas à histerectomia por apresentar maior risco para o câncer genital","D":"A recomendação é de não realizar o rastreamento em mulheres que não tenham iniciado atividade sexual"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878316","ankiGuid":"xf@.{2BgW"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-2ae9b30333e136af","number":"0255q","sourceNumber":"0255q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 22 anos iniciou atividade sexual há 6 meses e veio à consulta ginecológica para iniciar contracepção. Foi colhida a citologia para rastreio de câncer do colo uterino e o resultado apontou amostra satisfatória com células escamosas e metaplásicas e anormalidades em células escamosas compatíveis com lesão intraepitelial de baixo grau. O manejo adequado para esta paciente deve incluir:","options":{"A":"Prescrever a vacina para HPV (papilomavírus humano) e realizar colposcopia","B":"Encaminhar parceiro para exame e repetir citologia em seis meses","C":"Orientações de uso de preservativo e nova citologia em três anos","D":"Solicitar sorologias para Infecções sexualmente transmissíveis e realizar biópsia no colo uterino"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878317","ankiGuid":"cFv4,,d`F}"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-22e03d7938b6d826","number":"0256q","sourceNumber":"0256q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Gestante de 14 semanas realiza colpocitologia oncótica com resultado de lesão intraepitelial escamosa de baixo grau. A conduta adequada, nesse caso, é:","options":{"A":"indicar EZT","B":"indicar conização","C":"realizar colposcopia","D":"realizar captura híbrida"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878318","ankiGuid":"JTtm{%??|x"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-d0b418c3417ac608","number":"0257q","sourceNumber":"0257q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 19 anos de idade procura um ginecologista, para consulta de rotina, e informa que gostaria de realizar a coleta de exame citopatológico do colo do útero, pois já iniciou a vida sexual. Ao exame físico, o médico identifica paredes vaginais e colo do útero sem lesões visíveis a olho nu, e realiza coleta de material, conforme a técnica padrão. Após 15 dias, recebe o resultado do exame com diagnóstico de lesão intraepitelial escamosa de baixo grau (LSIL). A respeito desse caso clínico e considerando as Diretrizes Brasileiras para o Rastreamento de Câncer de Colo do Útero, assinale a alternativa correta.","options":{"A":"A coleta do exame citopatológico foi indicada corretamente, pois a paciente já teve relações sexuais, estando exposta ao vírus do HPV e, portanto, com chances de desenvolver lesões cervicais precursoras do câncer de colo do útero","B":"A paciente deverá ser encaminhada para a colposcopia","C":"A paciente deverá repetir o exame em seis meses","D":"A paciente deverá repetir o exame em um ano e, caso o resultado seja normal, deve realizar nova coleta somente aos 25 anos de idade","E":"A paciente deverá repetir o exame em três anos e, caso se mantenha com lesão intraepitelial escamosa de baixo grau (LSIL), deverá repetí-lo novamente em três anos"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878319","ankiGuid":"okt~Yur95)"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-90de440f688bf966","number":"0258q","sourceNumber":"0258q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"O uso de testes de biologia molecular para pesquisa de HPV de alto risco oncogênico no colo uterino pode ser utilizado como estratégia de rastreamento de câncer de colo. No Brasil, o principal motivo desta estratégia não ser utilizada é:","options":{"A":"Alta incidência de câncer em mulheres abaixo de 40 anos","B":"Uso da vacinação para HPV para meninos e meninas","C":"Alto custo dos testes moleculares para detecção de HPV","D":"Necessidade de migração para sistema de rastreamento organizado"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878320","ankiGuid":"J-~j!jK]^g"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-301bbb3cacb8ba37","number":"0259q","sourceNumber":"0259q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Em paciente com alteração histopatológica no colo uterino NIC 1 (lesão intraepitelial escamosa de baixo grau) em biopsia realizada durante colposcopia, a melhor conduta é:","options":{"A":"extensa cauterização elétrica da zona de transformação do colo","B":"histerectomia, pois são altos os índices de invasão no intervalo de 2 anos","C":"exérese da zona de transformação do colo, com análise imuno-histoquímica","D":"exérese da zona de transformação do colo, com análise anatomopatológica","E":"expectante, com controle citológico e colposcópico semestral"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878321","ankiGuid":"QmjH`1_1Kl"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-5dabd2a4463e2692","number":"0260q","sourceNumber":"0260q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma mulher de 35 anos comparece à Unidade Básica de Saúde (UBS) para receber o laudo do exame de Papanicolaou. O resultado revelou lesão intraepitelial de alto grau (LIEAG), candidíase e componente inflamatório moderado. Diante desse resultado, o médico da estratégia da saúde da família deverá","options":{"A":"convocar o marido para exame de peniscopia e, caso não seja detectada uma lesão por papilomavírus humano, acompanhar a paciente com preventivo semestral","B":"tratar a candidíase e orientar a paciente a repetir o preventivo semestralmente, pois a infecção por fungo é causa comum de LIEAG","C":"tratar a candidíase, indicar colposcopia e biópsia para identificar e confirmar lesões de alto grau","D":"indicar, de imediato, uma conização por se tratar de uma lesão de alto grau e, portanto, não é necessária colposcopia com biópsia"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878322","ankiGuid":"I-+ZL)$iZG"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-44c1cb8df8317fe3","number":"0261q","sourceNumber":"0261q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"A.L.G., 24 anos, G1C1, é usuária de pílula anticoncepcional (etinilestradiol 20 mcg + drospirenona 3 mg) e portadora do vírus HIV, usando medicação antirretroviral e com carga viral indetectável. Veio à consulta para ver resultado do Papanicolaou, que foi o seguinte: ASC-H - Células escamosas atípicas de significado indeterminado, não podendo excluir lesão intraepitelial de alto grau. Segundo as Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero, assinale a alternativa que apresenta a conduta correta para esse caso.","options":{"A":"A paciente não se encontra dentro da faixa etária recomendada para coleta citológica cervical","B":"A paciente deve ser orientada a retornar para consulta dentro de 6 meses para nova coleta de citologia cervical","C":"A paciente deve ser encaminhada ao serviço especializado para realização de colposcopia","D":"A paciente deve be submetida à coleta imediata de teste para detecção do DNA HPV","E":"A paciente deve ser orientada a retornar para consulta dentro de um ano para nova coleta de citologia cervical"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878323","ankiGuid":"gONtPcGipi"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-47ec7536cafc9630","number":"0262q","sourceNumber":"0262q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente com 54 anos de idade é portadora de lesão escamosa intraepitelial de alto grau identificada no exame citopatológico de rotina. A colposcopia demonstrou achados maiores (classificação Rio/2011) nos dois quadrantes superiores do colo do útero, sendo que tanto a junção escamo-colunar quanto os limites cranial e caudal foram visualizados no exame. Nesse caso, qual é a conduta correta?","options":{"A":"Histerectomia radical sem linfadenectomia","B":"Traquelectomia radical","C":"Amputação alargada do colo uterino","D":"Exérese da zona de transformação com a cirurgia de alta frequência","E":"Histerectomia total abdominal com retirada do terço superior de vagina"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878324","ankiGuid":"gnbBr#cZl#"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-20b712187055bf53","number":"0263q","sourceNumber":"0263q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente com 30 anos de idade está na 14ª semana de gestação e é portadora de resultado de exame citopatológico cérvico-vaginal compatível com lesão intraepitelial escamosa de alto grau (HSIL). Ao exame colposcópico, foram visualizadas alterações correspondentes a achados maiores (classificação Rio/2011), abrangendo os quatro quadrantes do colo uterino, porém sem critérios para lesão invasora. Qual é a conduta preconizada para esse caso?","options":{"A":"Repetir a citologia 90 dias após o parto","B":"Exérese da zona de transformação com a cirurgia de alta frequência","C":"Solicitar a coloração da lâmina da citologia inicial com o p16/ki67","D":"Realizar o teste do DNA-HPV","E":"Realizar biopsia da lesão em seus quatro quadrantes"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878325","ankiGuid":"k%!!X;1/en"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-ecf1796d2f3e1f8e","number":"0264q","sourceNumber":"0264q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 20 anos, sexualmente ativa, comparece a consulta de rotina com um resultado de colpocitologia tríplice compatível com lesão intraepitelial escamosa de baixo grau (LSIL). De acordo com as Diretrizes para o Rastreamento do Câncer do Colo do Útero de 2016, publicadas pelo Ministério da Saúde, a conduta mais adequada para essa paciente é:","options":{"A":"repetir o exame colpocitológico 6 meses após a data da coleta anterior","B":"realizar colposcopia e biópsia da lesão imediatamente","C":"repetir o exame colpocitológico 3 anos após a data da coleta anterior","D":"realizar captura híbrida para HPV para definir momento de nova colpocitologia"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878326","ankiGuid":"BBgyJ*S:7w"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-9683276aeb5711d8","number":"0265q","sourceNumber":"0265q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 17 anos, iniciou vida sexual há 1 ano. Comparece a consulta para avaliação de rotina. Sem queixas no momento. De acordo com as Diretrizes para o Rastreamento do Câncer do Colo do Útero de 2016, publicadas pelo Ministério da Saúde, essa paciente deve iniciar o rastreio de câncer cervical por meio de colpocitologia oncótica:","options":{"A":"a partir dos 20 anos de idade","B":"imediatamente","C":"2 anos após a sexarca","D":"a partir dos 25 anos de idade"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878327","ankiGuid":"l1D]~@R_X>"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-9526e09a76f9be19","number":"0266q","sourceNumber":"0266q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 27 anos, nuligesta, realizou colpocitologia oncótica que evidenciou lesão intraepitelial escamosa de baixo grau (LSIL). De acordo com as diretrizes estabelecidas pelo Ministério da Saúde – Instituto Nacional do Câncer (2016), a paciente deve ser orientada a:","options":{"A":"realizar colposcopia","B":"realizar exérese de zona de transformação","C":"repetir o exame colpocitológico em 12 meses na unidade de atenção primária","D":"repetir o exame colpocitológico em seis meses na unidade de atenção primária"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878328","ankiGuid":"jc6G=y($^Y"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-4c658744c398f87a","number":"0267q","sourceNumber":"0267q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"A colpocitologia oncológica é o estudo das células esfoliadas cervicovaginais, utilizada para o rastreamento do câncer de colo do útero. A coleta, o preparo e a interpretação da lâmina devem obedecer aos critérios de qualidade e a classificação vigente. É um exemplo de critério para o diagnóstico em patologia cervical:","options":{"A":"o achado de células escamosas e glandulares, na amostra, são considerados dentro dos limites da normalidade do material examinado","B":"o encontro de epitélio metaplásico é um achado anormal no exame colpocitológico","C":"as células atípicas de significado indeterminado são as escamosas (AGC) e as glandulares (ASC-US)","D":"a lesão intraepitelial de baixo grau compreende o NIC graus II e III"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878329","ankiGuid":"j@N}nW7@wA"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-101d431ada33ea70","number":"0268q","sourceNumber":"0268q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 56 anos de idade comparece à consulta com o ginecologista para revisão. Refere realizar exames ginecológicos de rastreamento, conforme orientação do médico clínico geral que a atendia até então. Informa que faz uso de cálcio, vitamina D e sinvastatina, por histórico de osteoporose identificada em densitometria óssea (DMO) prévia, e dislipidemia. Recentemente recebeu diagnóstico de nefrolitíase após crise de dor renal. Relata ser tabagista e etilista desde os 23 anos de idade, e o peso atual dela é 54 kg. Teve dois partos vaginais prévios, menarca aos 12 anos e menopausa aos 38 anos de idade. Nega ter realizado terapia de reposição hormonal. Considerando esse caso clínico e com base nas recomendações do Ministério da Saúde para exames de rastreamento e nos conhecimentos médicos correlatos, julgue os itens a seguir. A paciente poderia realizar o exame citopatológico do colo do útero a cada três anos, caso tenha dois resultados anuais consecutivos negativos.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878330","ankiGuid":"f_&<;Z5S,<"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-4917d9f6e1c7c6ed","number":"0269q","sourceNumber":"0269q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 32 anos, apresentou, na citologia oncótica, células escamosas atípicas de significado indeterminado (ASC-US). Segundo as Diretrizes Brasileiras para o Rastreamento de Câncer de Colo do Útero do Ministério da Saúde (2016), a conduta é:","options":{"A":"Encaminhar paciente para colposcopia","B":"Repetir o exame citológico em seis meses","C":"Repetir o exame citológico em três anos","D":"Realizar teste de detecção de DNA-HPV","E":"Realizar coleta de citologia em meio líquido em um ano"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878331","ankiGuid":"hgmrUpS~v$"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-bfc299226296cb5a","number":"0270q","sourceNumber":"0270q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Em relação ao rastreamento de câncer de colo uterino, o Ministério da Saúde recomenda que mulheres","options":{"A":"histerectomizadas não necessitam ser rastreadas","B":"que nunca tiveram atividade sexual não necessitam ser rastreadas","C":"na pós-menopausa não necessitam ser rastreadas","D":"com HIV não necessitam de rastreio diferente que as demais mulheres"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878332","ankiGuid":"Or/FMiCE7E"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-722b18082b512175","number":"0271q","sourceNumber":"0271q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 37 anos, G2PC2, com dois filhos vivos, vem à consulta na policlínica com resultado de citologia oncótica, há um mês, revelando: células glandulares atípicas. Realizou colposcopia e biópsia de colo, que mostrou adenocarcinoma in situ. Qual a melhor conduta a seguir?","options":{"A":"Nova citologia e exérese da zona de transformação","B":"Conização e histeroscopia com biópsia","C":"Histerectomia total com anexectomia","D":"Histerectomia total simples"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878333","ankiGuid":"k-IJJ@tr92"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-63912a0b4e1f0b29","number":"0272q","sourceNumber":"0272q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 27 anos, que se submetia a avaliações ginecológicas anuais na Unidade Básica de Saúde, sem registro de qualquer anormalidade até agora, trouxe à consulta o resultado do exame citopatológico cervical, que revelou lesão intraepitelial de baixo grau. A conduta mais adequada é","options":{"A":"repetir o exame citopatológico em 6 meses","B":"realizar biópsia de colo uterino","C":"realizar o teste de Schiller","D":"encaminhar a paciente para colposcopia e biópsia de colo uterino"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878334","ankiGuid":"g#+2h4qL4q"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-541d81fd2197c9b7","number":"0273q","sourceNumber":"0273q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Considere, na tabela a seguir, a idade de quatro pacientes e os seus respectivos resultados da citologia de colo uterino, coletada pelo médico da unidade básica de saúde (UBS). Segundo as diretrizes brasileiras para rastreamento do câncer de colo uterino (INCA 2016), o médico da UBS encaminhará para colposcopia imediata as pacientes","options":{"A":"I e III","B":"I e IV","C":"II e IV","D":"II e III"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878335","ankiGuid":"QPh$OyUnT9"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-36d320f0752fcb8e","number":"0274q","sourceNumber":"0274q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 21 anos, nuligesta, comparece a consulta na Unidade de Saúde Básica, com queixa de prurido e aparecimento de lesões em região genital.\n\nConforme a figura abaixo; A CONDUTA É:","options":{"A":"Coletar citologia cervical para definir conduta","B":"Encaminhar para exérese cirúrgica","C":"Aplicar acetato de clobetasol semanalmente","D":"Aplicar ácido tricloroacético a 80% semanalmente"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":["question_bank/media/ginecologia-rastreamento-do-cancer-de-colo-uterino/paste-5c0707920c500fc6b94ecf8b44b8b3954046783a.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878336","ankiGuid":"Jp0/`}xbi_"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-04611fa629403e4a","number":"0275q","sourceNumber":"0275q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 35a, G3P3C0, retorna à Unidade Básica de Saúde para resultado de colpocitologia com diagnóstico de atípia de células escamosas de significado indeterminado, possivelmente não neoplásica (ASC-US). Antecedente Pessoal: exérese da zona de transformação do colo do útero aos 28 anos. Anatomopatológico: lesão intraepitelial de alto grau/neoplasia intraepitelial cervical grau 3 com margem endocervical livre e ectocervical positiva. Recebeu alta após três anos de seguimento, sem evidências de recidiva. A CONDUTA É:","options":{"A":"Encaminhar para colposcopia","B":"Encaminhar para histerectomia","C":"Encaminhar para nova exérese de zona de transformação","D":"Repetir citologia em seis meses"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878337","ankiGuid":"eqA[Y(+5t7"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-071b67efb46ab564","number":"0276q","sourceNumber":"0276q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Nuligesta de 33 anos, hígida, em uso de anticoncepcional oral, veio à consulta com dois resultados de exames citopatológicos de colo uterino (realizados com intervalo de 6 meses) indicando células escamosas atípicas de significado indeterminado, possivelmente não neoplásicas (ASC-US). Com base nesse quadro, assinale a assertiva correta.","options":{"A":"Trata-se de uma alteração pouco frequente entre os exames alterados","B":"A prevalência de neoplasia intraepitelial de alto grau (NICII / NICIII) em mulheres com essa alteração citopatológica é alta","C":"A paciente deve realizar colposcopia","D":"A paciente deve realizar exame citopatológico em 6 meses","E":"A paciente deve realizar conização com cirurgia de alta frequência"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878338","ankiGuid":"KiGAYOtpby"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-479c95aeacf667bc","number":"0277q","sourceNumber":"0277q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Considere as assertivas abaixo sobre exame citopatológico de colo uterino, utilizado para o rastreamento do câncer de colo uterino. I - No Brasil, a recomendação é que o rastreamento seja iniciado aos 25 anos em mulheres com atividade sexual. II. - A ausência de células metaplásicas caracteriza amostra insatisfatória, devendo o exame ser repetido em 6 meses. III. - O rastreamento em gestantes segue as mesmas recomendações de periodicidade e de faixa etária das demais mulheres. Quais são corretas?","options":{"A":"Apenas I","B":"Apenas II","C":"Apenas III","D":"Apenas I e III","E":"I, II e III"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878339","ankiGuid":"v7hGM%;yqB"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-2b892c43d19263c9","number":"0278q","sourceNumber":"0278q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 38 anos de idade, assintomática, em seguimento ginecológico de rotina, recebeu resultado de citologia oncótica com atipia das células glandulares (AGC). Com base nesse caso hipotético, assinale a alternativa que apresenta a conduta mais adequada para a paciente.","options":{"A":"repetir exame imediatamente, associado à pesquisa para HPV","B":"repetir exame em seis meses","C":"investigação do canal endocervical com histeroscopia","D":"conização por cirurgia de alta frequência","E":"destruição da zona de transformação com ácido tricloroacético"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878340","ankiGuid":"OSw0OheA!F"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-0f688351d199eb66","number":"0279q","sourceNumber":"0279q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 39 anos de idade, IIG,IIP, apresenta lesão intraepitelial de alto grau de colo do útero em exame citológico. A colposcopia identifica área de mosaico adentrando o canal endocervical. A biópsia da lesão é compatível com microinvasão estromal. O passo seguinte é","options":{"A":"histeroscopia diagnóstica","B":"histerectomia total","C":"repetir colposcopia com estrogenioterapia","D":"curetagem uterina","E":"conização"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878341","ankiGuid":"q4O4?/Qyi:"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-3c2a68ec2996917f","number":"0280q","sourceNumber":"0280q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 30 anos realizou exame ginecológico de rotina. Exame citológico do colo do útero: sugestivo de cervicite folicular. A conduta mais adequada é","options":{"A":"realizar colposcopia","B":"tratar infecção por clamídia","C":"repetir exame citológico","D":"realizar ultrassonografia transvaginal"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878342","ankiGuid":"ivdlo~Y!CR"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-dc28b8ae7d8e61ba","number":"0281q","sourceNumber":"0281q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 27 anos, G3P3A0C0, apresenta secreção vaginal amarronzada de forte odor e sinusorragia recorrente. Última citologia oncótica há 02 anos: ASC-US. Exame ginecológico: extensa ectopia cervical -2 friável, lesão grosseira acetorreagente às “6 horas”. O próximo passo no seguimento dessa paciente é","options":{"A":"nova citologia oncótica","B":"colposcopia com biópsia cervical","C":"cirurgia de alta frequência","D":"eletrocauterização de ectopia cervical"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878343","ankiGuid":"wEGTMx~H>o"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-abbe723305bef6ed","number":"0282q","sourceNumber":"0282q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 22 anos, traz resultado de citologia oncótica com Atipia celular de significado indeterminado (ASC-US). Assinale a alternativa que indica corretamente a melhor conduta, segundo as diretrizes do Ministério da Saúde de 2016.","options":{"A":"colher nova citologia em 1 ano","B":"colposcopia com biopsia","C":"manter rotina trianual","D":"cauterização","E":"conização"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878344","ankiGuid":"kj>kEvUTu%"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-1ec450f3916e893b","number":"0283q","sourceNumber":"0283q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Quanto às infecções por papilomavírus humano (HPV) na gestação, pode-se afirmar que","options":{"A":"os altos níveis dos hormônios esteróides na gestação inibem a replicação do papilomavírus humano (HPV) o que explica a baixa prevalência da doença no período gravídico-puerperal","B":"biópsias dirigidas por colposcopias são contra-indicadas durante a gestação pois, apesar da alta sensibilidade na detecção do papilomavírus humano (HPV) e do câncer de colo uterino, estes procedimentos estão associados ao risco elevado de abortamentos","C":"as lesões induzidas pelo papilomavírus humano (HPV), independentemente do grau, constituem contra-indicação para o parto vaginal devido ao alto risco de contaminação fetal","D":"a aplicação de ácido tricloroacético (ATA), a vaporização com laser de CO₂, a cauterização com aparelho de cirurgia de alta frequência (CAF) e a criocauterização são opções para tratamento das lesões condilomatosas vulvares na gestação","E":"após confirmação diagnóstica de neoplasia intraepitelial cervical (NIC) de qualquer grau (I, II ou III) associada a infecção por papilomavírus humano (HPV) esta deve ser imediatamente tratada pelo risco de progressão da lesão durante a gestação"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878345","ankiGuid":"G]SA1D^}W."},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-41b4bf21ac33cdaf","number":"0284q","sourceNumber":"0284q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 32 anos de idade recebe laudo de citologia cervicovaginal com lesão intraepitelial de baixo grau. Foi solicitado que repetisse o exame em 6 meses, e o resultado foi normal. Segundo o Ministério da Saúde do Brasil, é recomendado, para essa mulher,","options":{"A":"repetir a citologia após 6 meses; se normal, continuar rastreio trienal","B":"pesquisar HPV; se positivo, realizar colposcopia com biópsia para definir conduta","C":"repetir a citologia após 1 ano; se normal, manter rastreio anual","D":"realizar colposcopia com biópsia nesse momento; se normais, manter rastreio anual","E":"manter controle citológico semestral por 2 anos; se normais, continuar com rastreio anual"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878346","ankiGuid":"F:S#:.tqsJ"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-5059a0726b093900","number":"0285q","sourceNumber":"0285q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"A infecção pelo papilomavírus humano:","options":{"A":"É sempre sintomática","B":"É transitória na maioria das mulheres","C":"É fator exclusivo na oncogênese cervical","D":"Tem prevalência baixa nos países desenvolvidos","E":"Os tipos 6 e 11 possuem significativa importância oncogênica"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878347","ankiGuid":"PAxF]c#{,W"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-ce18a1c264501252","number":"0286q","sourceNumber":"0286q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma mulher de 35 anos, prole constituída, comparece ao atendimento médico com o resultado de colpocitologia oncótica (CO), evidenciando metaplasia escamosa. O exame especular é normal. A conduta seguinte que deve ser adotada é:","options":{"A":"Histerectomia total","B":"Colposcopia e biópsia","C":"Cirurgia de alta frequência (CAF)","D":"Repetir a citologia em três meses","E":"Acompanhamento citológico de rotina"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878348","ankiGuid":"y&6O:F$;,^"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-eda1213a1de8da31","number":"0287q","sourceNumber":"0287q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 28 anos, traz à consulta seu citopatológico (CP) de rotina, coletado há 1 mês na unidade básica de saúde (UBS), com o seguinte resultado: Lesão Intraepitelial de Baixo Grau (LIEBG, LSIL). Refere que há 15 dias começou com secreção vaginal aumentada com odor fétido. Qual a melhor conduta segundo as Diretrizes Brasileiras para o rastreamento do câncer do colo do útero (INCA)?","options":{"A":"Repetir o CP imediatamente","B":"Encaminhar para colposcopia imediatamente","C":"Tratar o processo infeccioso e repetir o CP em 6 meses","D":"Tratar o processo infeccioso e encaminhar para colposcopia"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878349","ankiGuid":"I2!cty(fUq"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-5211cf1836f5087e","number":"0288q","sourceNumber":"0288q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"As Diretrizes brasileiras para o rastreamento do câncer no colo do útero de 2016 recomendam colheita de colpocitologia oncótica:","options":{"A":"em gestantes, deve ser feito fora do período gravídico-puerperal","B":"a partir dos 25 anos, independente da vida sexual","C":"até os 64 anos, com um exame anterior normal","D":"de 3 em 3 anos, desde que duas citologias anuais anteriores estejam normais"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878350","ankiGuid":"j`eYj|!(IU"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-6f87c213e6f25c1a","number":"0289q","sourceNumber":"0289q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Vem para consulta uma mulher de 50 anos com o seguinte histórico: quatro gestações, todas terminaram em parto por via vaginal, ainda menstrua regularmente. Seu esposo e único parceiro sexual da vida foi submetido a vasectomia logo após o nascimento de seu último filho há 15 anos e está impotente há 1 ano por complicações de um Diabete. A paciente faz acompanhamento com um clínico e seus exames laboratoriais, recentes estão normais. Afirma não ter realizado nenhuma consulta com ginecologista nos últimos sete anos. Nega casos de câncer de ovário ou de mama em familiares de primeiro grau. Assinale a alternativa que descreve os exames que devem ser solicitados para prevenção do câncer.","options":{"A":"Citologia oncótica, mamografia, ecografia mamaria, ecografia pélvica transvaginal","B":"Citologia oncótica, colonoscopia, mamografia, rastreamento da pele para lesões cutâneas","C":"Citologia oncótica, mamografia, CA-125, CA 19-9","D":"Colonoscopia, mamografia, rastreamento de pele para lesões cutâneas e pesquisa de CA-125"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878351","ankiGuid":"H|1m@n8_`m"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-65844ed0d21b9395","number":"0290q","sourceNumber":"0290q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente com 19 anos de idade e exame citológico compatível com lesão intraepitelial escamosa de alto grau (HSIL). No exame colposcópico, foi visualizado extensa placa ectocervical de epitélio branco em lábio superior e inferior do colo uterino, que corresponde a um achado maior pela Classificação da IFCPC-Rio 2011. Essa lesão é totalmente visualizada tanto em seu limite caudal como no cranial. Nesse caso, a melhor conduta é:","options":{"A":"repetir o exame citológico imediatamente","B":"indicar o método Ver X Tratar","C":"solicitar a volta da paciente em 6 meses para nova citologia","D":"solicitar a volta da paciente em 6 meses para a coleta do teste de DNA-HPV","E":"realizar biópsia da área correspondente ao epitélio branco"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878352","ankiGuid":"up[]?R(wi?"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-898dcb57e996887b","number":"0291q","sourceNumber":"0291q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Para que a amostra da Citologia Cérvico-Vaginal seja considerada satisfatória na sua análise de prevenção do câncer de colo uterino, o que deve ser observado?","options":{"A":"Índice colposcópico de Reid","B":"Índice de maturação estrogênica","C":"A presença de componentes da ZT (células metaplásicas endocervicais ou escamosas, ou ambas)","D":"Presença de Células-chave","E":"Uso de \"CellSaver\""},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878353","ankiGuid":"dVKjAoyB$u"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-3f8d1c7c2b0b519f","number":"0292q","sourceNumber":"0292q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Qual a conduta frente a um resultado de \"Lesão de Alto Grau\" em uma biopsia de Colo Uterino?","options":{"A":"Colposcopia","B":"Histeroscopia","C":"Histerectomia","D":"Conização","E":"Amputação do colo uterino"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878354","ankiGuid":"O~wBZ78(Qe"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-d2496cffef6584bf","number":"0293q","sourceNumber":"0293q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"O papilomavírus humano (HPV) teve sua associação com lesões de colo desde a década de 1970. Em 1983, Zur Hausen conseguiu clonar o DNA do HPV em pacientes com câncer de colo e recebeu o Prêmio Nobel de Medicina em 2008. Sobre esse vírus, é correto afirmar que","options":{"A":"os tipos de HPV mais encontrados nos casos de carcinoma de células escamosas do colo são o HPV 16 e o 18","B":"a citologia é o principal meio de rastreamento de câncer de colo, com acuidade próxima de 98%, mesmo em lesões precursoras iniciais, como a NIC I","C":"os principais tratamentos focais, químico, cirúrgico e uso de imunossupressores, visam erradicar o vírus","D":"as vacinas encontradas no mercado brasileiro são de vírus vivos atenuados, causando um aumento importante dos anticorpos capazes de destruir o HPV"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878355","ankiGuid":"fq)e)G7B>k"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-e265a354013e3492","number":"0294q","sourceNumber":"0294q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Paciente com 28 anos, mãe de dois filhos vivos, apresentando exame colpocitológico compatível com lesão escamosa de alto grau. Complementou a investigação com colposcopia que mostrou área de mosaico em lábio anterior que penetrava no canal endocervical. A biópsia da lesão mostrou neoplasia intra-epitelial grau 3. Qual a conduta a ser adotada?","options":{"A":"Controle com colpocitológico trimestral","B":"Ressonância nuclear magnética da pelve","C":"Conização (traquelectomia)","D":"Histerectomia total"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878356","ankiGuid":"d8.pN<EuQS"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-f09fb5e96b883fe4","number":"0295q","sourceNumber":"0295q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 24 anos, nuligesta, assintomática, sexualmente ativa em uso de preservativo regularmente, com ciclos menstruais regulares foi submetida a procedimento de inserção de DIU T de cobre 380A há 15 dias, quando estava menstruada. Retorna hoje à UBS para consulta de controle e mostrar ultrassonografia transvaginal também realizada hoje e que mostra: útero de 61cm³, endométrio de 8mm homogêneo, DIU normoposicionado, ovário direito e esquerdo sem alterações, ausência de líquido livre na pelve. Assinale a conduta MAIS ADEQUADA a ser tomada nessa consulta.","options":{"A":"Agendar retorno em 12 meses para citologia do colo uterino","B":"Orientar a paciente sobre a remoção do DIU T de cobre em 5 anos","C":"Prescrever contraceptivo oral combinado por 3 meses","D":"Solicitar ultrassonografia transvaginal anualmente"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878357","ankiGuid":"dnygtTSnfc"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-e91cdfbe3e27ed6a","number":"0296q","sourceNumber":"0296q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher nuligesta de 26 anos comparece à UBS com resultado de citologia cervical realizada há dois meses com o seguinte laudo anatomopatológico: \"células escamosas atípicas não podendo descartar lesão de alto grau (ASC-H)\". Ao exame especular, não apresenta lesões visíveis. A citologia cervical realizada há um ano foi negativa para malignidade. A conduta MAIS ADEQUADA é:","options":{"A":"indicar colposcopia e biópsia do colo uterino","B":"indicar conização do colo uterino","C":"repetir coleta de citologia cervical após 12 meses","D":"repetir coleta de citologia cervical após seis meses"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878358","ankiGuid":"DEQm_HDdg|"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-4fa47f94200b1e0d","number":"0297q","sourceNumber":"0297q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 26a, nuligesta, em uso de anticoncepcional oral (ACO), procura o Centro de Saúde para orientação sobre resultado de exame, colhido há 1 mês. Colpocitologia oncológica (Papanicolaou)= Células escamosas atípicas de significado indeterminado. Exames anteriores normais. ALÉM DE MEDIDAS DE SEXO SEGURO, É CORRETO ORIENTAR QUE:","options":{"A":"O exame está alterado, devendo-se realizar nova coleta em 1 ano e manter ACO","B":"O exame está normal, devendo-se realizar nova coleta em 3 anos e manter ACO","C":"O exame está alterado, devendo-se realizar colposcopia com biópsia e suspender ACO","D":"O exame está alterado, devendo-se realizar exérese da lesão com cirurgia de alta frequência e suspender ACO"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878359","ankiGuid":"MB6hTG/3ox"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-49cad552ab4e6936","number":"0298q","sourceNumber":"0298q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Uma mulher de 28 anos de idade retornou à Unidade Básica de Saúde com resultado citopatológico de lesão intraepitelial de baixo grau. Segundo as recomendações do Ministério da saúde, nesse caso hipotético, deve-se realizar","options":{"A":"nova coleta em doze meses","B":"agendamento de conização do colo uterino","C":"colposcopia","D":"nova coleta em seis meses","E":"nova coleta em 24 meses"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878360","ankiGuid":"bL5X#W|EA0"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-d791c15b584ecbe9","number":"0299q","sourceNumber":"0299q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Em 2018, a vacina HPV quadrivalente passou a ser disponível também para a população do sexo masculino, de 11 a 14 anos. A melhor justificativa para essa ampliação, além da redução da incidência do câncer de colo de útero e vulva nas mulheres pela transmissão do vírus para suas parceiras, é","options":{"A":"reduzir a incidência de câncer anal e de pênis, verrugas genitais e câncer de orofaringe e boca relacionados ao vírus","B":"reduzir a incidência de câncer retal e de pênis, verrugas genitais e linfoma relacionados ao vírus","C":"disponibilidade da vacina, uma vez que a resposta da população adolescente à campanha vacinal foi menor que a esperada","D":"seguir uma tendência de países como Inglaterra, ampliando o cuidado com a saúde do homem"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878361","ankiGuid":"vt&PBw(EPk"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-colo-uterino-d58ade981547da66","number":"02100q","sourceNumber":"02100q","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-colo-uterino","collectionLabel":"Anki · Rastreamento do Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Colo Uterino","subtopic":"","stem":"Mulher com 34 anos, G0P0, procurou UBS para saber resultado de biópsia do colo uterino após citologia compatível com lesão de alto grau (HSIL ou LIEAG) e colposcopia onde foi visualizado mosaico grosseiro. A biópsia foi guiada pela colposcopia. O laudo da biópsia foi compatível com carcinoma in situ. Qual a conduta apropriada para esta paciente?","options":{"A":"Colher material para determinar o subtipo de HPV","B":"Fazer conização para confirmação do diagnóstico","C":"Repetir citologia e colposcopia em seis meses","D":"Por ser tumor inicial fazer eletrocauterização da lesão"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Colo Uterino","Anki"],"ankiNoteId":"1755472878362","ankiGuid":"sAcUoDvNWs"}]};
